PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_user (id INTEGER PRIMARY KEY CHECK(id=1), salt TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions (digest TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS exercises (id TEXT PRIMARY KEY, revision INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_plans (id TEXT PRIMARY KEY, revision INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_days (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES workout_plans(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plan_exercises (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES workout_plans(id), exercise_id TEXT NOT NULL REFERENCES exercises(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_sessions (id TEXT PRIMARY KEY, revision INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS set_logs (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES workout_sessions(id), exercise_id TEXT NOT NULL REFERENCES exercises(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_operations (id TEXT PRIMARY KEY, digest TEXT NOT NULL);
-- Estruturas reservadas para as próximas fases. Todo conteúdo pessoal usa payload AES-256-GCM.
CREATE TABLE IF NOT EXISTS foods (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meals (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meal_items (id TEXT PRIMARY KEY, meal_id TEXT NOT NULL REFERENCES meals(id), food_id TEXT REFERENCES foods(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipes (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipe_items (id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL REFERENCES recipes(id), food_id TEXT REFERENCES foods(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_goals (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS body_measurements (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS imports (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS body_composition_entries (id TEXT PRIMARY KEY, import_id TEXT REFERENCES imports(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress_photos (id TEXT PRIMARY KEY, measurement_id TEXT REFERENCES body_measurements(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS goals (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS private_files (id TEXT PRIMARY KEY, import_id TEXT REFERENCES imports(id), photo_id TEXT REFERENCES progress_photos(id), payload BLOB NOT NULL);
PRAGMA user_version = 1;
